def gcd(a, b):
    """欧几里得递归:gcd(a, b) = gcd(b, a % b),递归到 b == 0 返回 a。
    先取绝对值,匹配 math.gcd 的非负约定(gcd(0, 0) == 0)。"""
    a, b = abs(a), abs(b)
    if b == 0:
        return a
    return gcd(b, a % b)

def exgcd(a, b):
    """扩展欧几里得:返回 (g, x, y),满足 a*x + b*y = g = gcd(a, b)(对非负整数定义)。
    递归求 exgcd(b, a % b) = (g, x1, y1),回代 x = y1,y = x1 - (a // b) * y1。"""
    if b == 0:
        return a, 1, 0
    g, x1, y1 = exgcd(b, a % b)
    return g, y1, x1 - (a // b) * y1


def mod_inverse(a, m):
    """a 关于模 m 的乘法逆元;存在当且仅当 gcd(a, m) == 1,否则返回 None。"""
    g, x, _ = exgcd(a % m, m)
    if g != 1:
        return None
    return x % m
